import ArchiveIcon from "@mui/icons-material/Archive";
import AutoModeIcon from "@mui/icons-material/AutoMode";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import TouchAppIcon from "@mui/icons-material/TouchApp";
import {
	Accordion,
	AccordionDetails,
	AccordionSummary,
	Box,
	Chip,
	IconButton,
	Paper,
	Tab,
	Tabs,
	Tooltip,
	Typography,
} from "@mui/material";
import type { GridRowId, GridValidRowModel } from "@mui/x-data-grid";
import type React from "react";
import { useCallback, useContext, useMemo, useState } from "react";
import type {
	DataGridColumn,
	DataGridExportTable,
} from "../../../../../components/Common/DataGrid/types";
import {
	createForecastsColumn,
	createStateColumn,
} from "../../../../../components/Common/FeatureListDataGrid/columns";
import FeatureListDataGrid from "../../../../../components/Common/FeatureListDataGrid/FeatureListDataGrid";
import FeatureProgressIndicator from "../../../../../components/Common/FeatureListDataGrid/FeatureProgressIndicator";
import FeatureName from "../../../../../components/Common/FeatureName/FeatureName";
import { FeatureLikelihoodChip } from "../../../../../components/Common/Forecasts/FeatureLikelihoodChip";
import { ForecastLevel } from "../../../../../components/Common/Forecasts/ForecastLevel";
import ProgressIndicator from "../../../../../components/Common/ProgressIndicator/ProgressIndicator";
import StyledLink from "../../../../../components/Common/StyledLink/StyledLink";
import WorkItemsDialog from "../../../../../components/Common/WorkItemsDialog/WorkItemsDialog";
import type { Delivery } from "../../../../../models/Delivery";
import type { IEntityReference } from "../../../../../models/EntityReference";
import type { IFeature } from "../../../../../models/Feature";
import { TERMINOLOGY_KEYS } from "../../../../../models/TerminologyKeys";
import type { IWorkItem } from "../../../../../models/WorkItem";
import { DeliverySelectionMode } from "../../../../../models/WorkItemRules";
import { ApiServiceContext } from "../../../../../services/Api/ApiServiceContext";
import { useTerminology } from "../../../../../services/TerminologyContext";
import { getWorkItemName } from "../../../../../utils/featureName";
import {
	CANNOT_FORECAST_SHORT,
	cannotBeForecast,
	cannotForecastReason,
} from "../../../../../utils/forecast/cannotForecast";
import { formatLikelihood } from "../../../../../utils/forecast/formatLikelihood";
import { INSUFFICIENT_FORECAST_DATA_SHORT } from "../../../../../utils/forecast/insufficientForecastData";
import { isForecastDataInsufficient } from "../../../../../utils/forecast/isForecastDataInsufficient";
import { jointLikelihoodLabel } from "../../../../../utils/forecast/jointLikelihoodLabel";
import { PREMIUM_UPGRADE_TOOLTIP } from "../../../../../utils/premiumUpgradeTooltip";
import DeliveryMetricsTab, {
	MINIMUM_METRIC_SNAPSHOTS,
	metricsUnavailableReason,
	useLazyMetricsHistory,
} from "./DeliveryMetricsTab";
import DeliveryNotesPanel from "./DeliveryNotesPanel";
import { buildDeliveryExportTable } from "./deliveryExportTable";

// A Feature's own chance of landing, not the Delivery's — the Delivery's asks whether they ALL land,
// so it sits below any single row's, and the heading must not invite the two to be read as one number.
const MARGINAL_LIKELIHOOD_HEADER = "Likelihood";

interface DeliverySectionProps {
	delivery: Delivery;
	features: IFeature[];
	isExpanded: boolean;
	isLoadingFeatures: boolean;
	onToggleExpanded: (deliveryId: number) => void;
	onDelete: (delivery: Delivery) => void;
	onEdit: (delivery: Delivery) => void;
	onArchive?: (delivery: Delivery) => void;
	teams: IEntityReference[];
	canEdit?: boolean;
	canArchive?: boolean;
}

const DeliverySection: React.FC<DeliverySectionProps> = ({
	delivery,
	features,
	isExpanded,
	isLoadingFeatures,
	onToggleExpanded,
	onDelete,
	onEdit,
	onArchive,
	teams,
	canEdit = true,
	canArchive = false,
}) => {
	const { featureService } = useContext(ApiServiceContext);

	const [selectedFeature, setSelectedFeature] = useState<IFeature | null>(null);
	const [featureWorkItems, setFeatureWorkItems] = useState<IWorkItem[]>([]);
	const [isWorkItemsDialogOpen, setIsWorkItemsDialogOpen] = useState(false);

	const [activeTab, setActiveTab] = useState<"workItems" | "metrics" | "notes">(
		"workItems",
	);
	const {
		history: metricsHistory,
		isLoading: isLoadingMetrics,
		hasFailed: metricsFailed,
		load: loadMetricsHistory,
	} = useLazyMetricsHistory(delivery.id);

	const isMetricsTabDisabled =
		delivery.metricSnapshotCount < MINIMUM_METRIC_SNAPSHOTS;

	const handleTabChange = useCallback(
		(
			_event: React.SyntheticEvent,
			nextTab: "workItems" | "metrics" | "notes",
		) => {
			if (nextTab === "metrics" && isMetricsTabDisabled) {
				return;
			}
			setActiveTab(nextTab);
			if (nextTab === "metrics") {
				loadMetricsHistory();
			}
		},
		[isMetricsTabDisabled, loadMetricsHistory],
	);

	const handleShowFeatureDetails = useCallback(
		async (feature: IFeature) => {
			setSelectedFeature(feature);
			setFeatureWorkItems([]);
			setIsWorkItemsDialogOpen(true);

			const items = await featureService.getFeatureWorkItems(feature.id);
			setFeatureWorkItems(items);
		},
		[featureService],
	);

	const handleCloseWorkItemsDialog = () => {
		setIsWorkItemsDialogOpen(false);
		setSelectedFeature(null);
	};

	const { getTerm } = useTerminology();
	const featureTerm = getTerm(TERMINOLOGY_KEYS.FEATURE);
	const featuresTerm = getTerm(TERMINOLOGY_KEYS.FEATURES);
	const workItemsTerm = getTerm(TERMINOLOGY_KEYS.WORK_ITEMS);
	const deliveryTerm = getTerm(TERMINOLOGY_KEYS.DELIVERY);
	const portfolioTerm = getTerm(TERMINOLOGY_KEYS.PORTFOLIO);

	// The grid hands back the ids in the order the reader is looking at them, so the file is sorted
	// and filtered the way the screen is.
	const exportTable = useCallback(
		(orderedRowIds: GridRowId[]): DataGridExportTable => {
			const featureById = new Map(
				features.map((feature) => [feature.id, feature]),
			);
			const orderedFeatures = orderedRowIds
				.map((rowId) => featureById.get(Number(rowId)))
				.filter((feature): feature is IFeature => feature !== undefined);

			return buildDeliveryExportTable(delivery, orderedFeatures, teams, {
				deliveryTerm,
				workItemsTerm,
				featureTerm,
				portfolioTerm,
			});
		},
		[
			delivery,
			features,
			teams,
			deliveryTerm,
			workItemsTerm,
			featureTerm,
			portfolioTerm,
		],
	);

	const isRuleBased =
		delivery.selectionMode === DeliverySelectionMode.RuleBased ||
		(delivery.selectionMode as unknown as string) === "RuleBased";

	const formatDate = (date: Date): string => {
		return new Date(date).toLocaleDateString("en-US", {
			month: "short",
			day: "numeric",
			year: "numeric",
		});
	};

	const columns: DataGridColumn<IFeature & GridValidRowModel>[] = useMemo(
		() => [
			{
				field: "name",
				headerName: `${featureTerm} Name`,
				hideable: false,
				minWidth: 120,
				flex: 1,
				renderCell: ({ row }) => (
					<FeatureName
						name={getWorkItemName(row.name, row.referenceId)}
						url={row.url ?? ""}
					/>
				),
			},
			{
				field: "owningTeam",
				headerName: "Team",
				minWidth: 100,
				flex: 0.5,
				renderCell: ({ row }) => {
					const teamsWithWork = teams.filter(
						(team) => row.getTotalWorkForTeam(team.id) > 0,
					);

					if (teamsWithWork.length === 0) {
						return (
							<Typography variant="body2" color="text.secondary">
								Unassigned
							</Typography>
						);
					}

					return (
						<Box sx={{ display: "flex", flexDirection: "column", gap: 0.5 }}>
							{teamsWithWork.map((team) => (
								<StyledLink key={team.id} to={`/teams/${team.id}`}>
									<Typography variant="body2">{team.name}</Typography>
								</StyledLink>
							))}
						</Box>
					);
				},
			},
			{
				field: "progress",
				headerName: "Progress",
				minWidth: 200,
				flex: 1,
				sortable: false,
				renderCell: ({ row }) => (
					<FeatureProgressIndicator
						feature={row}
						teams={teams}
						onShowDetails={() => handleShowFeatureDetails(row)}
					/>
				),
			},
			{
				...createForecastsColumn("Forecast"),
				minWidth: 100,
				flex: 0.5,
				width: undefined,
			},
			{
				field: "likelihood",
				headerName: MARGINAL_LIKELIHOOD_HEADER,
				minWidth: 110,
				flex: 0.3,
				sortable: false,
				renderCell: ({ row }) =>
					delivery.featureLikelihoods
						.filter((fl) => fl.featureId === row.id)
						.map((fl) => (
							<FeatureLikelihoodChip
								key={fl.featureId}
								featureLikelihood={fl}
								hasRemainingWork={row.getRemainingWorkForFeature() > 0}
							/>
						)),
			},
			createStateColumn(),
		],
		[featureTerm, delivery, teams, handleShowFeatureDetails],
	);

	const forecastLevel = new ForecastLevel(delivery.likelihoodPercentage);

	const teamsWithoutForecast = delivery.teamsWithoutForecast ?? [];
	const deliveryLikelihood = delivery.likelihoodPercentage;
	const deliveryCannotBeForecast =
		cannotBeForecast({ teamsWithoutForecast }) || deliveryLikelihood === null;

	const hasInsufficientData = isForecastDataInsufficient({
		hasRemainingWork: delivery.remainingWork > 0,
		hasSufficientData: delivery.hasSufficientData,
	});
	let likelihoodLabel: string;
	if (deliveryCannotBeForecast || deliveryLikelihood === null) {
		likelihoodLabel = CANNOT_FORECAST_SHORT;
	} else if (hasInsufficientData) {
		likelihoodLabel = INSUFFICIENT_FORECAST_DATA_SHORT;
	} else {
		likelihoodLabel = jointLikelihoodLabel({
			term: featuresTerm,
			date: delivery.getFormattedDate(),
			value: formatLikelihood(deliveryLikelihood, {
				hasRemainingWork: delivery.remainingWork > 0,
				precision: "round",
			}),
		});
	}

	return (
		<Paper elevation={1} sx={{ mb: 2, overflow: "hidden" }}>
			<Box sx={{ position: "relative" }}>
				<Accordion
					expanded={isExpanded}
					onChange={() => onToggleExpanded(delivery.id)}
					sx={{ overflow: "hidden" }}
					slotProps={{
						transition: {
							unmountOnExit: false,
						},
					}}
				>
					<AccordionSummary
						expandIcon={<ExpandMoreIcon />}
						sx={{
							minHeight: 80,
							position: "relative",
							"&.Mui-expanded": {
								minHeight: 80,
							},
							"& .MuiAccordionSummary-content": {
								alignItems: "center",
								margin: "12px 0",
								"&.Mui-expanded": {
									margin: "12px 0",
								},
							},
							pr: 15,
						}}
					>
						{canEdit && (
							<Box
								sx={{
									position: "absolute",
									top: "50%",
									transform: "translateY(-50%)",
									right: 8,
									zIndex: 1,
									display: "flex",
									alignItems: "center",
									gap: 0.5,
								}}
							>
								<Tooltip
									title={
										canArchive
											? `Archive ${deliveryTerm}`
											: PREMIUM_UPGRADE_TOOLTIP
									}
								>
									{/* The button is disabled without a licence, and a disabled button fires no
									    events, so the tooltip needs an enabled element of its own to sit on. */}
									<span>
										<IconButton
											size="small"
											disabled={!canArchive}
											onClick={(e) => {
												e.stopPropagation();
												onArchive?.(delivery);
											}}
											aria-label="archive"
											sx={{
												bgcolor: "background.paper",
												"&:hover": {
													bgcolor: "primary.light",
												},
											}}
										>
											<ArchiveIcon />
										</IconButton>
									</span>
								</Tooltip>
								<IconButton
									size="small"
									onClick={(e) => {
										e.stopPropagation();
										onEdit(delivery);
									}}
									aria-label="edit"
									sx={{
										bgcolor: "background.paper",
										"&:hover": {
											bgcolor: "primary.light",
										},
									}}
								>
									<EditIcon />
								</IconButton>
								<IconButton
									size="small"
									onClick={(e) => {
										e.stopPropagation();
										onDelete(delivery);
									}}
									aria-label="delete"
									sx={{
										bgcolor: "background.paper",
										"&:hover": {
											bgcolor: "error.light",
										},
									}}
								>
									<DeleteIcon />
								</IconButton>
							</Box>
						)}
						<Box
							sx={{
								display: "flex",
								flexDirection: "column",
								width: "100%",
								gap: 1,
							}}
						>
							<Box
								sx={{
									display: "flex",
									alignItems: "center",
									justifyContent: "space-between",
									width: "100%",
									gap: 4,
								}}
							>
								<Box
									sx={{
										display: "flex",
										flexDirection: "column",
										gap: 1,
										flex: 1,
									}}
								>
									<Box
										sx={{
											display: "flex",
											alignItems: "center",
											gap: 2,
											flexShrink: 0,
										}}
									>
										<Typography variant="h6" component="h3">
											{delivery.name}
										</Typography>
										<Tooltip
											title={
												isRuleBased
													? "Rule-Based: Features automatically update based on rules"
													: "Manual: Features are fixed"
											}
										>
											<Box sx={{ display: "flex", alignItems: "center" }}>
												{isRuleBased ? (
													<AutoModeIcon
														fontSize="small"
														sx={{ color: "text.secondary" }}
													/>
												) : (
													<TouchAppIcon
														fontSize="small"
														sx={{ color: "text.secondary" }}
													/>
												)}
											</Box>
										</Tooltip>
										<Typography variant="body2" color="text.secondary">
											Delivery Date: {delivery.getFormattedDate()}
										</Typography>
										<Chip
											title={
												deliveryCannotBeForecast
													? cannotForecastReason(teamsWithoutForecast)
													: undefined
											}
											label={likelihoodLabel}
											size="small"
											sx={{
												bgcolor: forecastLevel.color,
												color: "#fff",
												fontWeight: "bold",
											}}
										/>
									</Box>
									<Box
										sx={{
											display: "flex",
											alignItems: "center",
											gap: 1,
											flexWrap: "wrap",
										}}
									>
										<Typography variant="body2" color="text.secondary">
											Forecast:
										</Typography>
										{delivery.completionDates.map((forecast) => (
											<Chip
												key={forecast.probability}
												label={`${forecast.probability}%: ${formatDate(forecast.expectedDate)}`}
												size="small"
												variant="outlined"
											/>
										))}
									</Box>
								</Box>
								<Box
									sx={{
										display: "flex",
										alignItems: "center",
										justifyContent: "center",
										minWidth: 200,
										flex: 1,
									}}
								>
									<ProgressIndicator
										title={`${delivery.getFeatureCount()} ${delivery.getFeatureCount() === 1 ? featureTerm : featuresTerm} (${delivery.totalWork} ${workItemsTerm})`}
										progressableItem={{
											remainingWork: delivery.remainingWork,
											totalWork: delivery.totalWork,
										}}
										showDetails={true}
									/>
								</Box>
							</Box>
						</Box>
					</AccordionSummary>
					<AccordionDetails sx={{ p: 0 }}>
						<Tabs
							value={activeTab}
							onChange={handleTabChange}
							aria-label="delivery view tabs"
							sx={{ px: 2, borderBottom: 1, borderColor: "divider" }}
						>
							<Tab label={workItemsTerm} value="workItems" />
							<Tab
								value="metrics"
								disabled={isMetricsTabDisabled}
								label={
									<Tooltip
										title={
											isMetricsTabDisabled
												? metricsUnavailableReason(delivery.metricSnapshotCount)
												: ""
										}
									>
										<span style={{ pointerEvents: "auto" }}>Metrics</span>
									</Tooltip>
								}
							/>
							{/* Always enabled: unlike Metrics, a note needs no accumulated history. */}
							<Tab label="Notes" value="notes" />
						</Tabs>
						{activeTab === "workItems" && (
							<WorkItemsTab
								isLoadingFeatures={isLoadingFeatures}
								features={features}
								columns={columns}
								deliveryId={delivery.id}
								featuresTerm={featuresTerm}
								deliveryTerm={deliveryTerm}
								exportFileName={delivery.name}
								exportTable={exportTable}
							/>
						)}
						{activeTab === "metrics" && (
							<DeliveryMetricsTab
								isLoading={isLoadingMetrics}
								history={metricsHistory}
								hasFailed={metricsFailed}
								featuresTerm={featuresTerm}
							/>
						)}
						{activeTab === "notes" && (
							<DeliveryNotesPanel deliveryId={delivery.id} canWrite={canEdit} />
						)}
					</AccordionDetails>
				</Accordion>
			</Box>
			{selectedFeature && (
				<WorkItemsDialog
					title={`${getWorkItemName(selectedFeature.name, selectedFeature.referenceId)} ${workItemsTerm}`}
					items={featureWorkItems}
					open={isWorkItemsDialogOpen}
					onClose={handleCloseWorkItemsDialog}
				/>
			)}
		</Paper>
	);
};

interface WorkItemsTabProps {
	isLoadingFeatures: boolean;
	features: IFeature[];
	columns: DataGridColumn<IFeature & GridValidRowModel>[];
	deliveryId: number;
	featuresTerm: string;
	deliveryTerm: string;
	exportFileName: string;
	exportTable: (orderedRowIds: GridRowId[]) => DataGridExportTable;
}

const WorkItemsTab: React.FC<WorkItemsTabProps> = ({
	isLoadingFeatures,
	features,
	columns,
	deliveryId,
	featuresTerm,
	deliveryTerm,
	exportFileName,
	exportTable,
}) => {
	if (isLoadingFeatures) {
		return (
			<Typography variant="body2" color="text.secondary" sx={{ p: 2 }}>
				{`Loading ${featuresTerm}...`}
			</Typography>
		);
	}

	if (features.length === 0) {
		return (
			<Typography variant="body2" color="text.secondary" sx={{ p: 2 }}>
				No {featuresTerm} in this {deliveryTerm}.
			</Typography>
		);
	}

	return (
		<Box sx={{ mx: 2, mb: 2, mt: 2 }}>
			<FeatureListDataGrid
				features={features}
				columns={columns}
				storageKey={`delivery-features-${deliveryId}`}
				hideCompletedStorageKey={`lighthouse_hide_completed_features_delivery_${deliveryId}`}
				loading={false}
				emptyStateMessage={`No ${featuresTerm} found`}
				enableExport={true}
				exportFileName={exportFileName}
				exportTable={exportTable}
			/>
		</Box>
	);
};

export default DeliverySection;

import type { DataGridExportTable } from "../../../../../components/Common/DataGrid/types";
import type { IDelivery } from "../../../../../models/Delivery";
import type { ArchivedDelivery } from "../../../../../models/Delivery/ArchivedDelivery";
import type { FeatureMetric } from "../../../../../models/Delivery/DeliveryMetricsHistory";
import type { IEntityReference } from "../../../../../models/EntityReference";
import type { IFeature } from "../../../../../models/Feature";
import type { IWhenForecast } from "../../../../../models/Forecasts/WhenForecast";
import { formatLocalDate } from "../../../../../utils/date/localDate";
import { withheldName } from "../../../../../utils/dependencies/dependencySentences";
import { getWorkItemName } from "../../../../../utils/featureName";
import { featureWarningSentences } from "../../../../../utils/features/featureWarningSentences";
import {
	CANNOT_FORECAST_SHORT,
	cannotBeForecast,
} from "../../../../../utils/forecast/cannotForecast";
import { featureLikelihoodLabel } from "../../../../../utils/forecast/featureLikelihoodLabel";
import { formatLikelihood } from "../../../../../utils/forecast/formatLikelihood";

/** The words this instance uses, so an exported file reads in the reader's own vocabulary. */
export interface DeliveryExportTerms {
	deliveryTerm: string;
	workItemsTerm: string;
	featureTerm: string;
	portfolioTerm: string;
}

const FORECAST_PROBABILITIES = [50, 70, 85, 95] as const;

const HEADERS = [
	"Name",
	"Team",
	"Progress",
	...FORECAST_PROBABILITIES.map((probability) => `Forecast ${probability}%`),
	"Likelihood",
	"State",
	"Dependencies",
	"Warnings",
];

const NOTHING_TO_SAY = "";

const dateFor = (
	forecasts: readonly IWhenForecast[],
	probability: number,
): string => {
	const forecast = forecasts.find(
		(candidate) => candidate.probability === probability,
	);
	return forecast
		? formatLocalDate(new Date(forecast.expectedDate))
		: NOTHING_TO_SAY;
};

const progress = (total: number, remaining: number): string =>
	`${total - remaining}/${total}`;

const deliveryRow = (
	delivery: IDelivery,
	{ deliveryTerm }: DeliveryExportTerms,
): string[] => [
	`${delivery.name} (${deliveryTerm})`,
	NOTHING_TO_SAY,
	progress(delivery.totalWork, delivery.remainingWork),
	...FORECAST_PROBABILITIES.map((probability) =>
		dateFor(delivery.completionDates ?? [], probability),
	),
	delivery.likelihoodPercentage === null ||
	delivery.likelihoodPercentage === undefined
		? NOTHING_TO_SAY
		: `${Math.round(delivery.likelihoodPercentage)}%`,
	NOTHING_TO_SAY,
	NOTHING_TO_SAY,
	NOTHING_TO_SAY,
];

const teamsOn = (feature: IFeature, teams: IEntityReference[]): string => {
	const withWork = teams.filter(
		(team) => feature.getTotalWorkForTeam(team.id) > 0,
	);

	return withWork.length === 0
		? "Unassigned"
		: withWork.map((team) => team.name).join("; ");
};

const forecastCells = (feature: IFeature): string[] => {
	if (
		cannotBeForecast({ teamsWithoutForecast: feature.teamsWithoutForecast })
	) {
		return FORECAST_PROBABILITIES.map(() => CANNOT_FORECAST_SHORT);
	}

	return FORECAST_PROBABILITIES.map((probability) =>
		dateFor(feature.forecasts ?? [], probability),
	);
};

const likelihoodOf = (feature: IFeature, delivery: IDelivery): string => {
	const featureLikelihood = delivery.featureLikelihoods?.find(
		(candidate) => candidate.featureId === feature.id,
	);

	return featureLikelihood
		? featureLikelihoodLabel(
				featureLikelihood,
				feature.getRemainingWorkForFeature() > 0,
			)
		: NOTHING_TO_SAY;
};

const dependenciesOf = (
	feature: IFeature,
	terms: DeliveryExportTerms,
): string =>
	(feature.dependsOn ?? [])
		.map((dependency) =>
			dependency.isWithheld
				? withheldName(terms)
				: `${dependency.referenceId}: ${dependency.name}`,
		)
		.join("; ");

const featureRow = (
	feature: IFeature,
	delivery: IDelivery,
	teams: IEntityReference[],
	terms: DeliveryExportTerms,
): string[] => {
	const warnings = featureWarningSentences(
		{
			isDoneWithRemainingWork:
				feature.stateCategory === "Done" &&
				feature.getRemainingWorkForFeature() > 0,
			isUsingDefaultFeatureSize: feature.isUsingDefaultFeatureSize,
			dependencies: feature.dependsOn,
		},
		terms,
	);

	return [
		getWorkItemName(feature.name, feature.referenceId),
		teamsOn(feature, teams),
		progress(
			feature.getTotalWorkForFeature(),
			feature.getRemainingWorkForFeature(),
		),
		...forecastCells(feature),
		likelihoodOf(feature, delivery),
		feature.state ?? NOTHING_TO_SAY,
		dependenciesOf(feature, terms),
		warnings.length > 0 ? "Yes" : "No",
	];
};

/**
 * The whole exported table, written here rather than scraped off the grid: half these cells are drawn
 * by a renderer and have no backing field to read, so scraping them yields a raw array, a stale count
 * or nothing at all.
 *
 * A number nobody computed leaves as an empty cell. Writing 0, NaN or "null" into a status report
 * reads as a measurement, and the reader has no way to tell it apart from a real one.
 *
 * The Features arrive in the order the reader is looking at them in, and are emitted in that order.
 */
export function buildDeliveryExportTable(
	delivery: IDelivery,
	features: IFeature[],
	teams: IEntityReference[],
	terms: DeliveryExportTerms,
): DataGridExportTable {
	return {
		headers: HEADERS,
		rows: [
			deliveryRow(delivery, terms),
			...features.map((feature) => featureRow(feature, delivery, teams, terms)),
		],
	};
}

const archivedDeliveryRow = (
	archived: ArchivedDelivery,
	{ deliveryTerm }: DeliveryExportTerms,
): string[] => [
	`${archived.name} (${deliveryTerm})`,
	NOTHING_TO_SAY,
	progress(archived.totalWork, archived.remainingWork),
	...FORECAST_PROBABILITIES.map((probability) =>
		dateFor(archived.whenDistribution, probability),
	),
	archived.likelihoodPercentage === null
		? NOTHING_TO_SAY
		: `${Math.round(archived.likelihoodPercentage)}%`,
	NOTHING_TO_SAY,
	NOTHING_TO_SAY,
	NOTHING_TO_SAY,
];

// The record keeps how far along a Feature was as a percentage and how many items it held, so the
// same "done of total" cell a live export writes is recoverable exactly. A record written before
// item counts were kept has no total, and half a fraction is worse than none.
const pinnedProgress = (row: FeatureMetric): string =>
	row.totalItems === null
		? NOTHING_TO_SAY
		: `${Math.round((row.completion / 100) * row.totalItems)}/${row.totalItems}`;

const pinnedLikelihood = (row: FeatureMetric): string =>
	row.likelihood === null
		? CANNOT_FORECAST_SHORT
		: formatLikelihood(row.likelihood, {
				hasRemainingWork: row.completion < 100,
				precision: "round",
			});

const archivedFeatureRow = (row: FeatureMetric): string[] => [
	getWorkItemName(row.name, row.referenceId),
	NOTHING_TO_SAY,
	pinnedProgress(row),
	...FORECAST_PROBABILITIES.map(() => NOTHING_TO_SAY),
	pinnedLikelihood(row),
	NOTHING_TO_SAY,
	NOTHING_TO_SAY,
	pinnedWarning(row),
];

// A record that says the size was measured is answering the question, and answering it with a blank
// would read as nobody having asked. Only a row from before sizes were kept has nothing to say.
const pinnedWarning = (row: FeatureMetric): string => {
	if (row.isUsingDefaultSize === null || row.isUsingDefaultSize === undefined) {
		return NOTHING_TO_SAY;
	}

	return row.isUsingDefaultSize ? "Yes" : "No";
};

/**
 * The same table, for a Delivery that has been retired. Same columns and the same Delivery-first
 * shape, so a report built from a closed Delivery lines up beside one built from a running Delivery
 * without the reader having to notice which is which.
 *
 * The record never held a Feature's Team, state, dependencies or its own forecast dates, and those
 * cells are left empty rather than filled from anywhere. Anything written there would be today's
 * answer under a heading that promises the closing day's.
 */
export function buildArchivedDeliveryExportTable(
	archived: ArchivedDelivery,
	rows: readonly FeatureMetric[],
	terms: DeliveryExportTerms,
): DataGridExportTable {
	return {
		headers: HEADERS,
		rows: [
			archivedDeliveryRow(archived, terms),
			...rows.map(archivedFeatureRow),
		],
	};
}

import { useCallback, useContext, useEffect, useState } from "react";
import { useErrorSnackbar } from "../../../../../components/Common/SnackbarErrorHandler/SnackbarErrorHandler";
import type { Delivery } from "../../../../../models/Delivery";
import type { ArchivedDelivery } from "../../../../../models/Delivery/ArchivedDelivery";
import type { IFeature } from "../../../../../models/Feature";
import type { Portfolio } from "../../../../../models/Portfolio/Portfolio";
import { TERMINOLOGY_KEYS } from "../../../../../models/TerminologyKeys";
import type {
	DeliverySelectionMode,
	IWorkItemRuleCondition,
} from "../../../../../models/WorkItemRules";
import { ApiError } from "../../../../../services/Api/ApiError";
import { ApiServiceContext } from "../../../../../services/Api/ApiServiceContext";
import { useTerminology } from "../../../../../services/TerminologyContext";
import {
	archivedRefusalMessage,
	isArchivedRefusal,
	isNotArchivedRefusal,
	notArchivedRefusalMessage,
} from "../../../../../utils/deliveries/deliveryArchivedRefusal";

interface UseDeliveryManagementProps {
	portfolio: Portfolio;
}

// Deleting needs an id to act on and a name to put in the question, and nothing else - which is why
// a retired Delivery can go down the same path as a running one without pretending to be one.
export interface DeletableDelivery {
	id: number;
	name: string;
}

const CONCURRENCY_CONFLICT_STATUS = 409;

const STALE_VERSION_MESSAGE =
	"This was changed by someone else since you opened it. Refresh the page and try again.";

function isConcurrencyConflict(error: unknown): boolean {
	return (
		error instanceof ApiError && error.code === CONCURRENCY_CONFLICT_STATUS
	);
}

/**
 * Both refusals arrive as a conflict, and they call for opposite things: one says reload and try
 * again, the other says the Delivery is retired and no reload will change that. Telling somebody to
 * refresh a page that will say exactly the same thing is the failure this separates out.
 */
function refusalMessage(
	error: unknown,
	deliveryTerm: string,
	fallback: string,
): string {
	if (isArchivedRefusal(error)) {
		return archivedRefusalMessage(deliveryTerm);
	}

	if (isNotArchivedRefusal(error)) {
		return notArchivedRefusalMessage(deliveryTerm);
	}

	return isConcurrencyConflict(error) ? STALE_VERSION_MESSAGE : fallback;
}

export const useDeliveryManagement = ({
	portfolio,
}: UseDeliveryManagementProps) => {
	const { getTerm } = useTerminology();
	const deliveryTerm = getTerm(TERMINOLOGY_KEYS.DELIVERY);

	const [deliveries, setDeliveries] = useState<Delivery[]>([]);
	const [archivedDeliveries, setArchivedDeliveries] = useState<
		ArchivedDelivery[]
	>([]);
	const [isLoading, setIsLoading] = useState(false);
	const [showCreateModal, setShowCreateModal] = useState(false);
	const [selectedDelivery, setSelectedDelivery] = useState<Delivery | null>(
		null,
	);
	const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
	const [deliveryToDelete, setDeliveryToDelete] =
		useState<DeletableDelivery | null>(null);
	const [archiveDialogOpen, setArchiveDialogOpen] = useState(false);
	const [deliveryToArchive, setDeliveryToArchive] = useState<Delivery | null>(
		null,
	);
	const [expandedDeliveries, setExpandedDeliveries] = useState<Set<number>>(
		new Set(),
	);
	const [loadedFeatures, setLoadedFeatures] = useState<Map<number, IFeature[]>>(
		new Map(),
	);
	const [loadingFeaturesByDelivery, setLoadingFeaturesByDelivery] = useState<
		Set<number>
	>(new Set());

	const { deliveryService, featureService } = useContext(ApiServiceContext);
	const { showError } = useErrorSnackbar();

	const loadFeaturesForDelivery = useCallback(
		async (delivery: Delivery): Promise<void> => {
			if (
				loadingFeaturesByDelivery.has(delivery.id) ||
				loadedFeatures.has(delivery.id)
			)
				return;

			if (!delivery.features || delivery.features.length === 0) {
				setLoadedFeatures((prev) => new Map(prev).set(delivery.id, []));
				return;
			}

			setLoadingFeaturesByDelivery((prev) => new Set(prev).add(delivery.id));

			try {
				const featureIds = delivery.features;
				const features = await featureService.getFeaturesByIds(featureIds);
				setLoadedFeatures((prev) => new Map(prev).set(delivery.id, features));
			} catch (error) {
				console.error("Failed to load features for delivery:", error);
				showError("Failed to load features for delivery");
			} finally {
				setLoadingFeaturesByDelivery((prev) => {
					const next = new Set(prev);
					next.delete(delivery.id);
					return next;
				});
			}
		},
		[featureService, showError, loadingFeaturesByDelivery, loadedFeatures],
	);

	const forceReloadFeaturesForDelivery = useCallback(
		async (delivery: Delivery): Promise<void> => {
			if (loadingFeaturesByDelivery.has(delivery.id)) return;

			if (!delivery.features || delivery.features.length === 0) {
				setLoadedFeatures((prev) => new Map(prev).set(delivery.id, []));
				return;
			}

			setLoadingFeaturesByDelivery((prev) => new Set(prev).add(delivery.id));

			try {
				const featureIds = delivery.features;
				const features = await featureService.getFeaturesByIds(featureIds);
				setLoadedFeatures((prev) => new Map(prev).set(delivery.id, features));
			} catch (error) {
				console.error("Failed to load features for delivery:", error);
				showError("Failed to load features for delivery");
			} finally {
				setLoadingFeaturesByDelivery((prev) => {
					const next = new Set(prev);
					next.delete(delivery.id);
					return next;
				});
			}
		},
		[featureService, showError, loadingFeaturesByDelivery],
	);

	// A Delivery that has left the live list takes its expansion and its loaded Features with it,
	// so nothing is left holding rows for something that is no longer there to show them.
	const forgetDelivery = useCallback((deliveryId: number) => {
		setExpandedDeliveries((prev) => {
			const next = new Set(prev);
			next.delete(deliveryId);
			return next;
		});
		setLoadedFeatures((prev) => {
			const next = new Map(prev);
			next.delete(deliveryId);
			return next;
		});
	}, []);

	const fetchDeliveries = useCallback(async () => {
		setIsLoading(true);
		try {
			const portfolioDeliveries = await deliveryService.getByPortfolio(
				portfolio.id,
			);
			setDeliveries(portfolioDeliveries.active);
			setArchivedDeliveries(portfolioDeliveries.archived);
		} catch (error) {
			console.error("Failed to fetch deliveries:", error);
			showError("Failed to fetch deliveries");
		} finally {
			setIsLoading(false);
		}
	}, [deliveryService, portfolio.id, showError]);

	const handleAddDelivery = () => {
		setShowCreateModal(true);
	};

	const handleDeleteDelivery = (delivery: DeletableDelivery) => {
		setDeliveryToDelete(delivery);
		setDeleteDialogOpen(true);
	};

	const handleEditDelivery = (delivery: Delivery) => {
		setSelectedDelivery(delivery);
	};

	const handleArchiveDelivery = (delivery: Delivery) => {
		setDeliveryToArchive(delivery);
		setArchiveDialogOpen(true);
	};

	const handleCreateDelivery = async (deliveryData: {
		name: string;
		date: string;
		featureIds: number[];
		selectionMode?: DeliverySelectionMode;
		rules?: IWorkItemRuleCondition[];
		mode?: "and" | "or";
	}) => {
		try {
			await deliveryService.create(
				portfolio.id,
				deliveryData.name,
				new Date(deliveryData.date),
				deliveryData.featureIds,
				deliveryData.selectionMode,
				deliveryData.rules,
				deliveryData.mode,
			);
			setShowCreateModal(false);
			await fetchDeliveries();
		} catch (error) {
			console.error("Failed to create delivery:", error);
			showError("Failed to create delivery");
		}
	};

	const handleUpdateDelivery = async (deliveryData: {
		id: number;
		name: string;
		date: string;
		featureIds: number[];
		selectionMode?: DeliverySelectionMode;
		rules?: IWorkItemRuleCondition[];
		mode?: "and" | "or";
		concurrencyToken?: string;
	}) => {
		try {
			const wasExpanded = expandedDeliveries.has(deliveryData.id);

			await deliveryService.update({
				deliveryId: deliveryData.id,
				name: deliveryData.name,
				date: new Date(deliveryData.date),
				featureIds: deliveryData.featureIds,
				selectionMode: deliveryData.selectionMode,
				rules: deliveryData.rules,
				mode: deliveryData.mode,
				concurrencyToken: deliveryData.concurrencyToken,
			});
			setSelectedDelivery(null);
			setLoadedFeatures((prev) => {
				const next = new Map(prev);
				next.delete(deliveryData.id);
				return next;
			});
			await fetchDeliveries();

			if (wasExpanded) {
				const updatedDeliveries = await deliveryService.getByPortfolio(
					portfolio.id,
				);
				const updatedDelivery = updatedDeliveries.active.find(
					(d) => d.id === deliveryData.id,
				);
				if (updatedDelivery) {
					await forceReloadFeaturesForDelivery(updatedDelivery);
				}
			}
		} catch (error) {
			console.error("Failed to update delivery:", error);
			showError(
				refusalMessage(error, deliveryTerm, `Failed to update ${deliveryTerm}`),
			);
		}
	};

	const handleDeleteConfirmation = async (confirmed: boolean) => {
		if (confirmed && deliveryToDelete) {
			try {
				await deliveryService.delete(deliveryToDelete.id);
				forgetDelivery(deliveryToDelete.id);
				await fetchDeliveries();
			} catch (error) {
				console.error("Failed to delete delivery:", error);
				showError("Failed to delete delivery");
			}
		}

		setDeleteDialogOpen(false);
		setDeliveryToDelete(null);
	};

	const handleArchiveConfirmation = async (confirmed: boolean) => {
		if (confirmed && deliveryToArchive) {
			try {
				await deliveryService.archive(
					deliveryToArchive.id,
					deliveryToArchive.concurrencyToken,
				);
				forgetDelivery(deliveryToArchive.id);
				await fetchDeliveries();
			} catch (error) {
				console.error("Failed to archive delivery:", error);
				showError(
					refusalMessage(
						error,
						deliveryTerm,
						`Failed to archive ${deliveryTerm}`,
					),
				);
			}
		}

		setArchiveDialogOpen(false);
		setDeliveryToArchive(null);
	};

	const handleUnarchiveDelivery = async (delivery: ArchivedDelivery) => {
		try {
			await deliveryService.unarchive(delivery.id, delivery.concurrencyToken);
			await fetchDeliveries();
		} catch (error) {
			console.error("Failed to unarchive delivery:", error);
			showError(
				refusalMessage(
					error,
					deliveryTerm,
					`Failed to bring back ${deliveryTerm}`,
				),
			);
		}
	};

	const handleCloseCreateModal = () => {
		setShowCreateModal(false);
	};

	const handleCloseEditModal = () => {
		setSelectedDelivery(null);
	};

	const handleToggleExpanded = useCallback(
		(deliveryId: number) => {
			const isCurrentlyExpanded = expandedDeliveries.has(deliveryId);

			setExpandedDeliveries((prev) => {
				const next = new Set(prev);
				if (isCurrentlyExpanded) {
					next.delete(deliveryId);
				} else {
					next.add(deliveryId);
					const delivery = deliveries.find((d) => d.id === deliveryId);
					if (delivery) {
						loadFeaturesForDelivery(delivery);
					}
				}
				return next;
			});
		},
		[expandedDeliveries, deliveries, loadFeaturesForDelivery],
	);

	useEffect(() => {
		fetchDeliveries();
	}, [fetchDeliveries]);

	return {
		deliveries,
		archivedDeliveries,
		isLoading,
		showCreateModal,
		selectedDelivery,
		deleteDialogOpen,
		deliveryToDelete,
		archiveDialogOpen,
		deliveryToArchive,
		expandedDeliveries,
		loadedFeatures,
		loadingFeaturesByDelivery,

		handleAddDelivery,
		handleDeleteDelivery,
		handleEditDelivery,
		handleArchiveDelivery,
		handleArchiveConfirmation,
		handleUnarchiveDelivery,
		handleDeleteConfirmation,
		handleCloseCreateModal,
		handleCloseEditModal,
		handleCreateDelivery,
		handleUpdateDelivery,
		handleToggleExpanded,
	};
};

export default useDeliveryManagement;

