		expect(featureService.getFeaturesByIds).not.toHaveBeenCalled();
	});

	it("keeps Delete within reach while the record is open", async () => {
		renderSection();

		await openRecord();

		expect(screen.getByLabelText("delete")).toBeInTheDocument();
	});

	it("takes the numbers that were written down into a report", async () => {
		renderSection();

		await openRecord();
		await screen.findByText("Checkout rewrite");
		await userEvent.click(screen.getByTestId("export-button"));

		await waitFor(() =>
			expect(globalThis.URL.createObjectURL).toHaveBeenCalled(),
		);

		const lines = (await capturedCsv()).split("\n");
		expect(lines[0]).toBe(
			"Name,Team,Progress,Forecast 50%,Forecast 70%,Forecast 85%,Forecast 95%,Likelihood,State,Dependencies,Warnings",
		);
		expect(lines[1]).toContain("Autumn Launch (Delivery)");
		expect(lines[1]).toContain("40/50");
		expect(lines[2]).toContain("FTR-1: Checkout rewrite");
		expect(lines[2]).toContain("12/20");
	});

	it("opens the Metrics tab on a record with enough days behind it", async () => {
		const { deliveryService } = renderSection();

		await openRecord();
		const metricsTab = await screen.findByRole("tab", { name: "Metrics" });
		expect(metricsTab).not.toHaveAttribute("aria-disabled", "true");

		await userEvent.click(metricsTab);

		await waitFor(() =>
			expect(deliveryService.getMetricsHistory).toHaveBeenCalledWith(9),
		);
		expect(await screen.findByTestId("burnup-chart")).toBeInTheDocument();
	});

	it("keeps the Metrics tab dark on a record closed before it had enough days", async () => {
		const { deliveryService } = renderSection({
			archived: makeArchivedDelivery({ metricSnapshotCount: 2 }),
		});

		await openRecord();
		const metricsTab = await screen.findByRole("tab", { name: /Metrics/ });

		expect(metricsTab).toBeDisabled();
		expect(deliveryService.getMetricsHistory).not.toHaveBeenCalled();
	});

	it("still shows the Feature rows on a record whose Metrics tab is dark", async () => {
		renderSection({
			archived: makeArchivedDelivery({ metricSnapshotCount: 2 }),
		});

		await openRecord();

		expect(await screen.findByText("Checkout rewrite")).toBeInTheDocument();
	});

	it("lists the notes written before it closed, with nowhere to write another", async () => {
		renderSection({ notes: [note()] });

		await openRecord();
		await userEvent.click(await screen.findByRole("tab", { name: "Notes" }));

		expect(await screen.findByTestId("delivery-note")).toBeInTheDocument();
		expect(screen.queryByTestId("note-input")).not.toBeInTheDocument();
		expect(screen.queryByTestId("edit-note-button")).not.toBeInTheDocument();
		expect(screen.queryByTestId("delete-note-button")).not.toBeInTheDocument();
	});

	it("still says the Features were picked by a rule, and which rule", async () => {
		renderSection({
			archived: makeArchivedDelivery({
				selectionMode: "RuleBased",
				rules: [{ fieldKey: "tag", operator: "equals", value: "autumn" }],
				mode: "and",
			}),
		});

		await openRecord();

		expect(
			await screen.findByLabelText(/tag equals autumn/i),
		).toBeInTheDocument();
	});
});

import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { FeatureMetric } from "../../../../../models/Delivery/DeliveryMetricsHistory";
import ArchivedFeatureGrid from "./ArchivedFeatureGrid";

const { mockUseLicenseRestrictions } = vi.hoisted(() => ({
	mockUseLicenseRestrictions: vi.fn(),
}));

vi.mock("../../../../../hooks/useLicenseRestrictions", () => ({
	useLicenseRestrictions: mockUseLicenseRestrictions,
}));

const pinnedRows: FeatureMetric[] = [
	{
		referenceId: "FTR-1",
		name: "Checkout rewrite",
		completion: 60,
		likelihood: 72,
		totalItems: 20,
		isUsingDefaultSize: false,
	},
	{
		referenceId: "FTR-2",
		name: "Search relevance",
		completion: 100,
		likelihood: null,
		totalItems: 8,
		isUsingDefaultSize: true,
	},
];

const renderGrid = (rows: FeatureMetric[] = pinnedRows) =>
	render(
		<ArchivedFeatureGrid
			rows={rows}
			deliveryId={9}
			featureTerm="Feature"
			featuresTerm="Features"
			workItemsTerm="Work Items"
			exportFileName="Autumn Launch"
			exportTable={vi.fn()}
		/>,
	);

describe("ArchivedFeatureGrid", () => {
	beforeEach(() => {
		localStorage.clear();
		mockUseLicenseRestrictions.mockReturnValue({
			licenseStatus: { canUsePremiumFeatures: true },
			isLoading: false,
		});
	});

	it("lists exactly the Feature rows that were written down", () => {
		renderGrid();

		expect(screen.getByText("Checkout rewrite")).toBeInTheDocument();
		expect(screen.getByText("Search relevance")).toBeInTheDocument();
		expect(screen.getByText("FTR-1")).toBeInTheDocument();
		expect(screen.getByText("FTR-2")).toBeInTheDocument();
	});

	it("shows each row's totals as they were noted", () => {
		renderGrid();

		expect(screen.getByText("60%")).toBeInTheDocument();
		expect(screen.getByText("72%")).toBeInTheDocument();
		expect(screen.getByText("20")).toBeInTheDocument();
		expect(screen.getByText("8")).toBeInTheDocument();
	});

	it("carries only the columns the record held", () => {
		renderGrid();

		expect(screen.getByText("Reference")).toBeInTheDocument();
		expect(screen.getByText("Feature Name")).toBeInTheDocument();
		expect(screen.getByText("Completion")).toBeInTheDocument();
		expect(screen.getByText("Likelihood")).toBeInTheDocument();
		expect(screen.getByText("Work Items")).toBeInTheDocument();

		expect(screen.queryByText("State")).not.toBeInTheDocument();
		expect(screen.queryByText("Team")).not.toBeInTheDocument();
		expect(screen.queryByText("Forecast")).not.toBeInTheDocument();
		expect(screen.queryByText("Depends On")).not.toBeInTheDocument();
	});

	it("offers no way through to the Feature as it stands today", () => {
		renderGrid();

		expect(screen.queryByRole("link")).not.toBeInTheDocument();
	});

	it("says a Feature could not be forecast rather than showing a blank chance", () => {
		renderGrid();

		expect(screen.getByText("Cannot forecast")).toBeInTheDocument();
	});

	it("marks the Feature whose size was a default rather than a count", () => {
		renderGrid();

		expect(screen.getByText("Estimated")).toBeInTheDocument();
	});

	it("says so when the Delivery closed holding no Features at all", () => {
		renderGrid([]);

		expect(screen.getByText("No Features in this record")).toBeInTheDocument();
	});

	it("shows a dash where a row recorded before sizes were kept has no count", () => {
		renderGrid([
			{
				referenceId: "FTR-9",
				name: "Older row",
				completion: 40,
				likelihood: null,
				totalItems: null,
				isUsingDefaultSize: null,
			},
		]);

		expect(screen.getByText("Older row")).toBeInTheDocument();
		expect(screen.getByText("—")).toBeInTheDocument();
	});
});

