			const { result } = renderHook(() => useDeliveryManagement({ portfolio }));

			await waitFor(() => {
				expect(result.current.isLoading).toBe(false);
			});

			act(() => {
				result.current.handleArchiveDelivery(delivery);
			});

			await act(async () => {
				await result.current.handleArchiveConfirmation(false);
			});

			expect(mockDeliveryService.archive).not.toHaveBeenCalled();
			expect(result.current.archiveDialogOpen).toBe(false);
			expect(result.current.deliveries).toEqual([delivery]);
		});

		it("says a stale version was refused rather than reporting a plain failure", async () => {
			const portfolio = getMockPortfolio();
			const delivery = getMockDelivery({ id: 1 });

			mockDeliveryService.getByPortfolio.mockResolvedValue(
				portfolioDeliveries([delivery]),
			);
			mockDeliveryService.archive.mockRejectedValue(
				new ApiError(409, "Request failed with status code 409"),
			);

			const { result } = renderHook(() => useDeliveryManagement({ portfolio }));

			await waitFor(() => {
				expect(result.current.isLoading).toBe(false);
			});

			act(() => {
				result.current.handleArchiveDelivery(delivery);
			});

			await act(async () => {
				await result.current.handleArchiveConfirmation(true);
			});

			expect(mockShowError).toHaveBeenCalledWith(
				expect.stringMatching(/changed by someone else/i),
			);
		});

		it("brings a retired Delivery back on the version it was last written at", async () => {
			const portfolio = getMockPortfolio();
			const retired = archivedRow(9, "Autumn Launch");

			mockDeliveryService.getByPortfolio.mockResolvedValue(
				portfolioDeliveries([], [retired]),
			);
			mockDeliveryService.unarchive.mockResolvedValue(undefined);

			const { result } = renderHook(() => useDeliveryManagement({ portfolio }));

			await waitFor(() => {
				expect(result.current.isLoading).toBe(false);
			});

			await act(async () => {
				await result.current.handleUnarchiveDelivery(retired);
			});

			expect(mockDeliveryService.unarchive).toHaveBeenCalledWith(
				9,
				"22222222-2222-2222-2222-222222222222",
			);
			expect(mockDeliveryService.getByPortfolio).toHaveBeenCalledTimes(2);
		});
	});
});

import { render, screen, waitFor } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { IDeliveryNote } from "../../../../../models/Delivery/DeliveryNote";
import { ApiError } from "../../../../../services/Api/ApiError";
import { ApiServiceContext } from "../../../../../services/Api/ApiServiceContext";
import {
	createMockApiServiceContext,
	createMockDeliveryService,
} from "../../../../../tests/MockApiServiceProvider";
import { DELIVERY_ARCHIVED_CODE } from "../../../../../utils/deliveries/deliveryArchivedRefusal";
import DeliveryNotesPanel from "./DeliveryNotesPanel";

const note = (overrides: Partial<IDeliveryNote> = {}): IDeliveryNote => ({
	id: 1,
	deliveryId: 42,
	text: "Two Features added after the steering review",
	createdAt: "2026-08-21T10:00:00Z",
	createdOn: "2026-08-21",
	lastEditedAt: null,
	lastEditedOn: null,
	authorDisplayName: "Anoop Kumar",
	canModify: true,
	...overrides,
});

const mockDeliveryService = createMockDeliveryService();

const renderPanel = (props?: { isReadOnly?: boolean; canWrite?: boolean }) => {
	const context = createMockApiServiceContext({
		deliveryService: mockDeliveryService,
	});

	return render(
		<ApiServiceContext.Provider value={context}>
			<DeliveryNotesPanel
				deliveryId={42}
				canWrite={props?.canWrite ?? true}
				isReadOnly={props?.isReadOnly ?? false}
			/>
		</ApiServiceContext.Provider>,
	);
};

const archivedRefusal = () =>
	new ApiError(
		409,
		"Request failed with status code 409",
		undefined,
		undefined,
		DELIVERY_ARCHIVED_CODE,
	);

describe("DeliveryNotesPanel on an archived Delivery", () => {
	beforeEach(() => {
		vi.clearAllMocks();
		vi.mocked(mockDeliveryService.getNotes).mockResolvedValue([]);
	});

	it("still lists the notes that were written before it closed", async () => {
		vi.mocked(mockDeliveryService.getNotes).mockResolvedValue([
			note({ id: 2, text: "newer" }),
			note({ id: 1, text: "older" }),
		]);

		renderPanel({ isReadOnly: true });

		await waitFor(() =>
			expect(screen.getAllByTestId("delivery-note")).toHaveLength(2),
		);
	});

	it("offers nowhere to type a new one", async () => {
		renderPanel({ isReadOnly: true });

		await waitFor(() =>
			expect(screen.getByTestId("delivery-notes-panel")).toBeInTheDocument(),
		);
		expect(screen.queryByTestId("note-input")).not.toBeInTheDocument();
		expect(screen.queryByTestId("save-note-button")).not.toBeInTheDocument();
	});

	it("offers no way to correct or withdraw a note, even to the person who wrote it", async () => {
		vi.mocked(mockDeliveryService.getNotes).mockResolvedValue([note()]);

		renderPanel({ isReadOnly: true });

		await screen.findByTestId("delivery-note");
		expect(screen.queryByTestId("edit-note-button")).not.toBeInTheDocument();
		expect(screen.queryByTestId("delete-note-button")).not.toBeInTheDocument();
	});

	it("says the Delivery is archived when the server refuses a new note for that reason", async () => {
		vi.mocked(mockDeliveryService.addNote).mockRejectedValue(archivedRefusal());

		renderPanel();

		await userEvent.type(await screen.findByTestId("note-input"), "late note");
		await userEvent.click(screen.getByTestId("save-note-button"));

		expect(
			await screen.findByText(/Delivery is archived/i),
		).toBeInTheDocument();
	});

	it("says the Delivery is archived when the server refuses a correction for that reason", async () => {
		vi.mocked(mockDeliveryService.getNotes).mockResolvedValue([note()]);
		vi.mocked(mockDeliveryService.updateNote).mockRejectedValue(
			archivedRefusal(),
		);

		renderPanel();

		await screen.findByTestId("delivery-note");
		await userEvent.click(screen.getByTestId("edit-note-button"));
		await userEvent.type(screen.getByTestId("edit-note-input"), " corrected");
		await userEvent.click(screen.getByTestId("save-edit-button"));

		expect(
			await screen.findByText(/Delivery is archived/i),
		).toBeInTheDocument();
	});

	it("says the Delivery is archived when the server refuses a withdrawal for that reason", async () => {
		vi.mocked(mockDeliveryService.getNotes).mockResolvedValue([note()]);
		vi.mocked(mockDeliveryService.deleteNote).mockRejectedValue(
			archivedRefusal(),
		);

		renderPanel();

		await screen.findByTestId("delivery-note");
		await userEvent.click(screen.getByTestId("delete-note-button"));

		expect(
			await screen.findByText(/Delivery is archived/i),
		).toBeInTheDocument();
	});

	it("keeps the ordinary failure wording for a refusal that has nothing to do with archiving", async () => {
		vi.mocked(mockDeliveryService.addNote).mockRejectedValue(
			new ApiError(500, "boom"),
		);

		renderPanel();

		await userEvent.type(await screen.findByTestId("note-input"), "late note");
		await userEvent.click(screen.getByTestId("save-note-button"));

		expect(
			await screen.findByText("The note could not be saved."),
		).toBeInTheDocument();
	});
});

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import ArchiveConfirmationDialog from "./ArchiveConfirmationDialog";

vi.mock("../../../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) =>
			({ delivery: "Commitment", deliveries: "Commitments" })[key] ?? key,
	}),
}));

const renderDialog = (overrides?: {
	onConfirm?: () => void;
	onCancel?: () => void;
}) =>
	render(
		<ArchiveConfirmationDialog
			open={true}
			itemName="Phoenix Release"
			onConfirm={overrides?.onConfirm ?? vi.fn()}
			onCancel={overrides?.onCancel ?? vi.fn()}
		/>,
	);

describe("ArchiveConfirmationDialog", () => {
	it("names the Delivery it is about to retire", () => {
		renderDialog();

		expect(screen.getAllByText(/Phoenix Release/).length).toBeGreaterThan(0);
	});

	it("says the three things archiving does: it delists, it pins the numbers, it can be undone", () => {
		renderDialog();

		const body = document.body.textContent ?? "";

		expect(body).toMatch(/out of the active/i);
		expect(body).toMatch(/numbers it shows right now/i);
		expect(body).toMatch(/bring it back/i);
	});

	it("says archiving is not deleting, and that deleting stays available on it", () => {
		renderDialog();

		const body = document.body.textContent ?? "";

		expect(body).toMatch(/not the same as deleting/i);
		expect(body).toMatch(/can still be deleted/i);
	});

	// Archiving and deleting both remain, and delete still takes the written-down numbers with it.
	// A reader who leaves this dialog believing an archived Delivery is out of harm's way is being
	// set up to archive one instead of backing it up, so the promise this must never make is a
	// promise of safety.
	it.each([
		"safe",
		"protect",
		"secure",
		"permanent",
		"forever",
		"backup",
		"back up",
		"preserv",
		"cannot be lost",
		"cannot be deleted",
		"cannot be removed",
		"read-only",
	])("never promises the Delivery is %s", (forbidden) => {
		renderDialog();

		const body = (document.body.textContent ?? "").toLowerCase();

		expect(body).not.toContain(forbidden);
	});

	it("uses the tenant's word for a Delivery rather than the word Delivery", () => {
		renderDialog();

		const body = document.body.textContent ?? "";

		expect(body).toMatch(/Commitment/);
		expect(body).not.toMatch(/Delivery/);
	});

	it("does nothing until the reader chooses", async () => {
		const onConfirm = vi.fn();
		const onCancel = vi.fn();
		renderDialog({ onConfirm, onCancel });

		expect(onConfirm).not.toHaveBeenCalled();

		await userEvent.click(screen.getByRole("button", { name: "Cancel" }));

		expect(onCancel).toHaveBeenCalledTimes(1);
		expect(onConfirm).not.toHaveBeenCalled();
	});

	it("archives when the reader confirms", async () => {
		const onConfirm = vi.fn();
		renderDialog({ onConfirm });

		await userEvent.click(screen.getByRole("button", { name: "Archive" }));

		expect(onConfirm).toHaveBeenCalledTimes(1);
	});
});

import { render, screen } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { ArchivedDelivery } from "../../../../../models/Delivery/ArchivedDelivery";
import { ApiServiceContext } from "../../../../../services/Api/ApiServiceContext";
import { makeArchivedDelivery } from "../../../../../tests/ArchivedDeliveryFixture";
import {
	createMockApiServiceContext,
	createMockDeliveryService,
} from "../../../../../tests/MockApiServiceProvider";
import ArchivedDeliveriesSection from "./ArchivedDeliveriesSection";

const { mockUseLicenseRestrictions } = vi.hoisted(() => ({
	mockUseLicenseRestrictions: vi.fn(),
}));

vi.mock("../../../../../hooks/useLicenseRestrictions", () => ({
	useLicenseRestrictions: mockUseLicenseRestrictions,
}));

vi.mock("../../../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) =>
			({
				delivery: "Delivery",
				deliveries: "Deliveries",
				feature: "Feature",
				features: "Features",
				workItems: "Work Items",
			})[key] ?? key,
	}),
}));

const makeArchived = makeArchivedDelivery;

const renderSection = (props?: {
	archived?: ArchivedDelivery[];
	canEdit?: boolean;
	onDelete?: (delivery: ArchivedDelivery) => void;
	onUnarchive?: (delivery: ArchivedDelivery) => void;
	canUsePremiumFeatures?: boolean;
}) => {
	mockUseLicenseRestrictions.mockReturnValue({
		licenseStatus: {
			canUsePremiumFeatures: props?.canUsePremiumFeatures ?? true,
		},
		isLoading: false,
	});

	const deliveryService = createMockDeliveryService();
	const context = createMockApiServiceContext({ deliveryService });

	render(
		<ApiServiceContext.Provider value={context}>
			<ArchivedDeliveriesSection
				archivedDeliveries={props?.archived ?? [makeArchived()]}
				canEdit={props?.canEdit ?? true}
				onDelete={props?.onDelete ?? vi.fn()}
				onUnarchive={props?.onUnarchive ?? vi.fn()}
			/>
		</ApiServiceContext.Provider>,
	);

	return { deliveryService };
};

const expand = async () =>
	userEvent.click(screen.getByRole("button", { name: /Archived Deliveries/ }));

describe("ArchivedDeliveriesSection", () => {
	beforeEach(() => {
		vi.clearAllMocks();
		localStorage.clear();
	});

	it("says nothing at all when a Portfolio has retired nothing", () => {
		renderSection({ archived: [] });

		expect(screen.queryByText(/Archived/)).not.toBeInTheDocument();
	});

	it("is folded away until someone opens it", () => {
		renderSection();

		expect(
			screen.getByRole("button", { name: /Archived Deliveries/ }),
		).toHaveAttribute("aria-expanded", "false");
	});

	it("shows the name, the date and the numbers that were written down once opened", async () => {
		renderSection();

		await expand();

		expect(await screen.findByText("Autumn Launch")).toBeInTheDocument();
		expect(
			screen.getByText(
				new RegExp(
					`Delivery Date: ${makeArchived().getFormattedDate().replace(/\//g, "\\/")}`,
				),
			),
		).toBeInTheDocument();
		expect(screen.getByText(/80% \(40\/50\)/)).toBeInTheDocument();
		expect(screen.getByText(/All Features by .*: 64%/)).toBeInTheDocument();
	});

	it("marks the retired Delivery as archived, and says on which day", async () => {
		renderSection();

		await expand();

		expect(await screen.findByTestId("archived-marker")).toHaveTextContent(
			`Archived: ${makeArchived().getFormattedArchivedOn()}`,
		);
	});

	it("still says why a Delivery that closed without a forecast has no number", async () => {
		renderSection({
			archived: [
				makeArchived({
					likelihoodPercentage: null,
					teamsWithoutForecast: ["Team Alpha"],
				}),
			],
		});

		await expand();

		expect(screen.getByText("Cannot forecast")).toBeInTheDocument();
	});

	it("keeps Delete available on a retired Delivery", async () => {
		const onDelete = vi.fn();
		renderSection({ onDelete });

		await expand();
		await userEvent.click(screen.getByLabelText("delete"));

		expect(onDelete).toHaveBeenCalledTimes(1);
		expect(onDelete.mock.calls[0][0].id).toBe(9);
	});

	it("offers no Delete to a reader who may not change the Portfolio", async () => {
		renderSection({ canEdit: false });

		await expand();

		expect(screen.queryByLabelText("delete")).not.toBeInTheDocument();
	});

	it("offers a way to bring a retired Delivery back", async () => {
		const onUnarchive = vi.fn();
		renderSection({ onUnarchive });

		await expand();
		await userEvent.click(screen.getByLabelText("unarchive"));

		expect(onUnarchive).toHaveBeenCalledTimes(1);
		expect(onUnarchive.mock.calls[0][0].id).toBe(9);
	});

	it("lets a lapsed instance bring a Delivery back, so nobody is left stranded in the archive", async () => {
		const onUnarchive = vi.fn();
		renderSection({ onUnarchive, canUsePremiumFeatures: false });

		await expand();
		const unarchive = screen.getByLabelText("unarchive");

		expect(unarchive).not.toBeDisabled();

		await userEvent.click(unarchive);
		expect(onUnarchive).toHaveBeenCalledTimes(1);
	});

	it("offers no way back to a reader who may not change the Portfolio", async () => {
		renderSection({ canEdit: false });

		await expand();

		expect(screen.queryByLabelText("unarchive")).not.toBeInTheDocument();
	});
});

